/**
 * Namespace `operations` (Phase 7 slice 7g-4; decision 0025 point 2): what an installation is operated with, from the
 * web app instead of a terminal.
 *
 *  - The first-run set-up (no session; the database refuses it once set up, and without the one-time token the
 *    installer printed, kernel 1375): the site, its time zone, the first system administrator and process owner with
 *    their first passwords (BOOTSTRAP credentials, changed at the first sign-in), this browser as the administrator's
 *    console, and the seal key generated by the server. The installation kind is fixed at provisioning: shown, never
 *    chosen here.
 *  - Demo and test data (demo and sandbox installations only; tablets 1485 refuses them on any other GMP one): load the
 *    demo data, or reset the installation to a clean state. Both recreate the database and lose everything in it; the
 *    request names the database to confirm it. They run as a job whose state is read without a session (the session
 *    goes with the database).
 *  - Backups (kernel 1376; DI-45): a backup now and its record, the catalogue with size, time and hash, and a copy of a
 *    stored artefact (encrypted as stored).
 *  - The background workers (the integration adapters' workers and the analytics runner): start, stop, restart, with
 *    the reason recorded (PLATFORM.OPERATE); an adapter refused on its transport (EBMR-INT-034) is refused here too.
 *  - The simulators' test console (demo and sandbox only): start and stop each simulator of apps/simulators as a child
 *    process of the server, and switch its faults.
 *
 * Counts and sizes travel as whole-number text. Every act is attributed to the person signed in (none is signed).
 */
import { z } from 'zod';
import { InstallationKind, Instant, Uuid } from '../common.ts';
import { defineRoute } from '../route.ts';
import { IntegrationSourceSystem } from './integrations.ts';

const WholeText = z.string().regex(/^(0|[1-9][0-9]{0,18})$/, 'a whole number as text');
const ReasonText = z.string().trim().min(1).max(1000);
const DatabaseName = z.string().regex(/^[a-z][a-z0-9_]{1,62}$/);

// ------------------------------------------------------------------------------------------------ first-run set-up

export const SetupStateView = z.strictObject({
  /** True until the first administrator and process owner exist. */
  required: z.boolean(),
  installation: InstallationKind,
  /** The database carries the demo marker (tab.demo_installation; D-P7g4-1). */
  demo: z.boolean(),
  /** An unused, unexpired set-up token exists (never the token). */
  tokenIssued: z.boolean(),
  /** The site policy site.zone now (the set-up may change it, DI-27). */
  siteZone: z.string(),
  /** The site of the set-up in progress; null before it, and once set up (the state is read without a session). */
  site: z.strictObject({ code: z.string(), name: z.string() }).nullable(),
  /**
   * GENERATE: the server has a seal key path (EBMR_SEAL_KEY_FILE) with no key in it, and generates one at the set-up;
   * PRESENT: a key file is there already; NOT_CONFIGURED: no path (signatures are refused until one is configured).
   */
  sealKey: z.enum(['GENERATE', 'PRESENT', 'NOT_CONFIGURED']),
});
export type SetupStateView = z.infer<typeof SetupStateView>;

const SetupPerson = z.strictObject({
  legalName: z.string().trim().min(1).max(200),
  loginName: z.string().trim().min(3).max(64),
  /** The first password (a BOOTSTRAP credential: changed at the first sign-in). */
  password: z.string().min(12).max(200),
});

export const SetupRequest = z.strictObject({
  /** The one-time set-up token the installer printed. */
  token: z.string().min(32).max(256),
  site: z.strictObject({
    code: z.string().trim().min(1).max(32),
    name: z.string().trim().min(1).max(200),
    /** An IANA time zone of a place (or UTC), DI-27. */
    zone: z.string().trim().min(1).max(64),
  }),
  administrator: SetupPerson,
  processOwner: SetupPerson,
  /** This browser's device key (SPKI DER, base64): it becomes the administrator's console (BOOTSTRAP-CONSOLE-1). */
  consoleSpki: z.string().min(40).max(2000),
  /** Generate the seal key now (only when the state says GENERATE). */
  generateSealKey: z.boolean(),
});
export type SetupRequest = z.infer<typeof SetupRequest>;

export const SetupDoneView = z.strictObject({
  siteCode: z.string(),
  siteZone: z.string(),
  administratorLogin: z.string(),
  processOwnerLogin: z.string(),
  /** The administrator's console: this browser. */
  consoleDeviceCode: z.string(),
  /** The seal key registered for the installation, or null when none was generated. */
  sealKeyId: z.string().nullable(),
});
export type SetupDoneView = z.infer<typeof SetupDoneView>;

// ------------------------------------------------------------------------------------------------ demo and test data

export const DemoJobView = z.strictObject({
  state: z.enum(['IDLE', 'RUNNING', 'DONE', 'FAILED']),
  kind: z.enum(['LOAD', 'RESET']).nullable(),
  /** What the job is doing now (or did last). */
  step: z.string().nullable(),
  error: z.string().nullable(),
  /** Whole seconds since the job started. */
  elapsedSeconds: WholeText.nullable(),
});
export type DemoJobView = z.infer<typeof DemoJobView>;

export const InstallationContentsView = z.strictObject({
  persons: WholeText,
  accounts: WholeText,
  devices: WholeText,
  batches: WholeText,
  signatures: WholeText,
  auditEntries: WholeText,
});

export const DemoView = z.strictObject({
  /** The conveniences run here (a sandbox, or a demo installation). */
  allowed: z.boolean(),
  /** Why not, as the database says it (EBMR-OPS-010), or what the server lacks. */
  refusal: z.string().nullable(),
  installation: InstallationKind,
  demo: z.boolean(),
  database: z.string(),
  /** The GMP review batch and packaging-order demo can be built (a GMP demo installation). */
  reviewBatchAllowed: z.boolean(),
  /** What a load or a reset removes. */
  contents: InstallationContentsView,
  job: DemoJobView,
});
export type DemoView = z.infer<typeof DemoView>;

const Confirm = {
  reason: ReasonText,
  /** The database's name, typed by the person to confirm that everything in it is lost. */
  confirmDatabase: DatabaseName,
};

// ------------------------------------------------------------------------------------------------ backups

export const BackupView = z.strictObject({
  backupId: z.string(),
  tier: z.enum(['RETENTION_GRADE', 'OPERATIONAL']),
  method: z.string(),
  databaseName: z.string(),
  sha256: z.string().regex(/^[0-9a-f]{64}$/),
  sizeBytes: WholeText,
  storageUri: z.string(),
  immutableUntil: z.string().nullable(),
  encryptionKeyRef: z.string(),
  toolVersion: z.string(),
  snapshotTakenAt: Instant,
  recordedAt: Instant,
  /** This server holds the artefact (its own backup directory) and can hand a copy to the screen. */
  downloadable: z.boolean(),
});
export type BackupView = z.infer<typeof BackupView>;

export const BackupRunView = z.strictObject({
  jobRunId: Uuid,
  jobName: z.string(),
  tier: z.enum(['RETENTION_GRADE', 'OPERATIONAL']),
  status: z.enum(['SUCCEEDED', 'FAILED']),
  backupId: z.string().nullable(),
  error: z.string().nullable(),
  startedAt: Instant,
  finishedAt: Instant,
});
export type BackupRunView = z.infer<typeof BackupRunView>;

export const BackupRequestView = z.strictObject({
  requestId: Uuid,
  tier: z.enum(['RETENTION_GRADE', 'OPERATIONAL']),
  reason: z.string(),
  by: z.string(),
  recordedAt: Instant,
});

export const BackupsView = z.strictObject({
  /** The server can run a backup (backup directory, key and the backup service identity configured). */
  configured: z.boolean(),
  /** What is missing when it cannot. */
  problem: z.string().nullable(),
  backups: z.array(BackupView),
  runs: z.array(BackupRunView),
  requests: z.array(BackupRequestView),
});
export type BackupsView = z.infer<typeof BackupsView>;

export const BackupFileView = z.strictObject({
  backupId: z.string(),
  fileName: z.string(),
  sizeBytes: WholeText,
  sha256: z.string(),
  /** The stored artefact (AES-256-GCM encrypted as stored), base64. */
  contentBase64: z.string(),
  /** The manifest written beside it (JSON text). */
  manifest: z.string(),
});
export type BackupFileView = z.infer<typeof BackupFileView>;

// ------------------------------------------------------------------------------------------------ background workers

export const WorkerView = z.strictObject({
  kind: z.enum(['ADAPTER', 'ANALYTICS']),
  /** The adapter's code, or ANALYTICS. */
  code: z.string(),
  sourceSystem: IntegrationSourceSystem.nullable(),
  running: z.boolean(),
  /** The worker's state (IDLE, RUNNING, RETRYING, BLOCKED), or STOPPED. */
  state: z.enum(['IDLE', 'RUNNING', 'RETRYING', 'BLOCKED', 'STOPPED']),
  /** Why it does not run when it was refused (EBMR-INT-034 for an adapter's transport), or its last error. */
  problem: z.string().nullable(),
});
export type WorkerView = z.infer<typeof WorkerView>;

export const OperationsActView = z.strictObject({
  act: z.string(),
  target: z.string(),
  outcome: z.enum(['DONE', 'REFUSED']),
  detail: z.string().nullable(),
  reason: z.string(),
  by: z.string(),
  at: Instant,
});

export const WorkersView = z.strictObject({
  workers: z.array(WorkerView),
  /** The last 20 operations of the workers, newest first. */
  acts: z.array(OperationsActView),
});
export type WorkersView = z.infer<typeof WorkersView>;

// ------------------------------------------------------------------------------------------------ simulators

export const SimulatorCode = z.enum(['ERP', 'WMS', 'QMS', 'LIMS', 'LMS', 'CMMS', 'EMS', 'L3', 'OPCUA']);
export type SimulatorCode = z.infer<typeof SimulatorCode>;

export const SimulatorView = z.strictObject({
  code: SimulatorCode,
  title: z.string(),
  running: z.boolean(),
  /** The simulator's control and console address while it runs (loopback). */
  url: z.string().nullable(),
  /** The base URL an adapter reads (the endpoint of its service-keys entry), while it runs. */
  endpoint: z.string().nullable(),
  /** The faults switched on now. */
  faults: z.array(z.string()),
  /** Every fault the simulator knows. */
  available: z.array(z.string()),
  /** Why it stopped by itself, when it did (its last output line). */
  problem: z.string().nullable(),
});
export type SimulatorView = z.infer<typeof SimulatorView>;

export const SimulatorsView = z.strictObject({
  allowed: z.boolean(),
  refusal: z.string().nullable(),
  simulators: z.array(SimulatorView),
});
export type SimulatorsView = z.infer<typeof SimulatorsView>;

export const operations = {
  setupState: defineRoute({
    id: 'operations.setupState',
    method: 'GET',
    path: '/api/setup/state',
    installation: 'ANY',
    auth: 'NONE',
    mutating: false,
    summary: 'Whether this installation still needs its first-run set-up, its kind, zone and seal-key state (no names, no token)',
    response: SetupStateView,
  }),
  setup: defineRoute({
    id: 'operations.setup',
    method: 'POST',
    path: '/api/setup',
    installation: 'ANY',
    auth: 'NONE',
    mutating: true,
    summary: 'The first-run set-up with the installer\'s one-time token: the site, its zone, the first administrator and process owner, the seal key',
    body: SetupRequest,
    response: SetupDoneView,
  }),
  demo: defineRoute({
    id: 'operations.demo',
    method: 'GET',
    path: '/api/operations/demo',
    installation: 'ANY',
    auth: 'SESSION',
    mutating: false,
    summary: 'Demo and test data: whether this installation allows them, what a load or reset removes, the job',
    response: DemoView,
  }),
  demoLoad: defineRoute({
    id: 'operations.demoLoad',
    method: 'POST',
    path: '/api/operations/demo/load',
    installation: 'ANY',
    auth: 'SESSION',
    mutating: true,
    summary: 'Recreate this demo or sandbox installation with the demo data (personas, terminals, feature seeds; optionally the GMP review batch); everything in it is lost',
    body: z.strictObject({ ...Confirm, reviewBatch: z.boolean(), packaging: z.boolean() }),
    response: z.strictObject({ job: DemoJobView }),
  }),
  demoReset: defineRoute({
    id: 'operations.demoReset',
    method: 'POST',
    path: '/api/operations/demo/reset',
    installation: 'ANY',
    auth: 'SESSION',
    mutating: true,
    summary: 'Reset this demo or sandbox installation to a clean state awaiting its first-run set-up; everything in it is lost',
    body: z.strictObject(Confirm),
    response: z.strictObject({ job: DemoJobView, setupToken: z.string() }),
  }),
  demoJob: defineRoute({
    id: 'operations.demoJob',
    method: 'GET',
    path: '/api/operations/demo/job',
    installation: 'ANY',
    auth: 'NONE',
    mutating: false,
    summary: 'The state of the demo load or reset job (read without a session: the session goes with the database)',
    response: DemoJobView,
  }),
  backups: defineRoute({
    id: 'operations.backups',
    method: 'GET',
    path: '/api/operations/backups',
    installation: 'ANY',
    auth: 'SESSION',
    mutating: false,
    summary: 'The backup catalogue, the job runs and the requests (CONTINUITY.BACKUP_READ)',
    response: BackupsView,
  }),
  runBackup: defineRoute({
    id: 'operations.runBackup',
    method: 'POST',
    path: '/api/operations/backups',
    installation: 'ANY',
    auth: 'SESSION',
    mutating: true,
    summary: 'A backup now (CONTINUITY.BACKUP_RUN): requested by the person, run and recorded by the backup service identity',
    body: z.strictObject({ reason: ReasonText, tier: z.enum(['RETENTION_GRADE', 'OPERATIONAL']) }),
    response: z.strictObject({ requestId: Uuid, run: BackupRunView.nullable(), error: z.string().nullable() }),
  }),
  backupFile: defineRoute({
    id: 'operations.backupFile',
    method: 'GET',
    path: '/api/operations/backups/:backupId/file',
    installation: 'ANY',
    auth: 'SESSION',
    mutating: false,
    summary: 'A copy of one stored backup artefact, as stored (encrypted), with its manifest (CONTINUITY.BACKUP_RUN; each copy is recorded)',
    params: z.strictObject({ backupId: z.string().regex(/^[A-Za-z0-9._:-]{8,128}$/) }),
    response: BackupFileView,
  }),
  workers: defineRoute({
    id: 'operations.workers',
    method: 'GET',
    path: '/api/operations/workers',
    installation: 'ANY',
    auth: 'SESSION',
    mutating: false,
    summary: 'The server\'s background workers (integration adapters, the analytics runner) and their last operations',
    response: WorkersView,
  }),
  controlWorker: defineRoute({
    id: 'operations.controlWorker',
    method: 'POST',
    path: '/api/operations/workers/:code',
    installation: 'ANY',
    auth: 'SESSION',
    mutating: true,
    summary: 'Start, stop or restart one background worker, with the reason (PLATFORM.OPERATE)',
    params: z.strictObject({ code: z.string().regex(/^[A-Z][A-Z0-9_-]{1,63}$/) }),
    body: z.strictObject({ action: z.enum(['START', 'STOP', 'RESTART']), reason: ReasonText }),
    response: WorkerView,
  }),
  simulators: defineRoute({
    id: 'operations.simulators',
    method: 'GET',
    path: '/api/operations/simulators',
    installation: 'ANY',
    auth: 'SESSION',
    mutating: false,
    summary: 'The simulators\' test console (demo and sandbox installations): each simulator, whether it runs, its faults',
    response: SimulatorsView,
  }),
  controlSimulator: defineRoute({
    id: 'operations.controlSimulator',
    method: 'POST',
    path: '/api/operations/simulators/:simulator',
    installation: 'ANY',
    auth: 'SESSION',
    mutating: true,
    summary: 'Start or stop one simulator (demo and sandbox installations; PLATFORM.OPERATE)',
    params: z.strictObject({ simulator: SimulatorCode }),
    body: z.strictObject({ action: z.enum(['START', 'STOP']), reason: ReasonText }),
    response: SimulatorView,
  }),
  simulatorFault: defineRoute({
    id: 'operations.simulatorFault',
    method: 'POST',
    path: '/api/operations/simulators/:simulator/faults',
    installation: 'ANY',
    auth: 'SESSION',
    mutating: true,
    summary: 'Switch one fault of a running simulator on or off (demo and sandbox installations; PLATFORM.OPERATE)',
    params: z.strictObject({ simulator: SimulatorCode }),
    body: z.strictObject({ fault: z.string().regex(/^[A-Z][A-Z_]{1,40}$/), on: z.boolean(), reason: ReasonText }),
    response: SimulatorView,
  }),
} as const;
